594	    const wxString text = wxControl::Ellipsize(GetLabel(), dc, wxELLIPSIZE_END, available);

150	    return p.text_secondary;
151	}
152	
153	// A filament colour, or the dashed ring of a colour nobody chose. Both are
154	// drawn at the same size so rows stay aligned either way.
155	void draw_dot(wxGraphicsContext& gc, const std::optional<wxColour>& dot, double x, double y, double size,
156	              const ShellPalette& p)
157	{
158	    if (!dot) return;
159	    if (dot->IsOk()) {
160	        // A quiet ring keeps a white or near-background colour visible.
161	        gc.SetPen(wxPen(p.border_subtle));
162	        gc.SetBrush(wxBrush(*dot));
163	    } else {
164	        wxPen dashed(p.text_secondary, 1, wxPENSTYLE_SHORT_DASH);
165	        gc.SetPen(dashed);
166	        gc.SetBrush(*wxTRANSPARENT_BRUSH);
167	    }
168	    gc.DrawEllipse(x, y, size, size);
169	}
170	
171	} // namespace
172	
173	void draw_header_icon(wxGraphicsContext& gc, HeaderIcon icon, double x, double y, double size, const wxColour& color)
174	{
175	    if (const char* asset = icon_asset(icon))
176	        gc.DrawBitmap(icon_bitmap(asset, std::max(1, int(std::lround(size))), color), x, y, size, size);
177	    else if (icon != HeaderIcon::None)
178	        draw_custom_icon(gc, icon, x, y, size, color);
179	}

