{
    if (!dot) return;
    if (!dot->IsOk()) {
        draw_dashed_ring(gc, p.text_secondary, x, y, size, dash, gap);
        return;
    }
    // A quiet ring keeps a white or near-background colour visible.
    gc.SetPen(wxPen(p.border_subtle));
    gc.SetBrush(wxBrush(*dot));
    gc.DrawEllipse(x, y, size, size);
}

