+        path.MoveToPoint(cx + radius * std::cos(start), cy + radius * std::sin(start));
+        path.AddArc(cx, cy, radius, start, start + sweep, true);
+    }
+    gc.SetPen(gc.CreatePen(wxGraphicsPenInfo(colour).Cap(wxCAP_BUTT)));
+    gc.StrokePath(path);
